// Settings: edit these before going live.
const settings = {
  spreadsheet_id: 'YOUR_SPREADSHEET_ID',
  sheet_name: 'Leads',          // columns A to H: Name, Email, Phone, Company, Stage, Owner, Notes, CRM status
  status_column: 'H',
  default_country_code: '+971', // for local numbers such as 050 000 0101
  stages: { New: 'lead', Qualified: 'salesqualifiedlead', Opportunity: 'opportunity', Customer: 'customer' },
  owner_ids: { Sara: '1001', Omar: '1002' },  // sheet owner name -> HubSpot owner ID; unknown names are left unassigned
  batch_size: 100,              // HubSpot batch limit
};

const j = $input.first().json;
const fromWebhook = 'webhookUrl' in j;
const q = fromWebhook ? (j.query || {}) : {};
const body = fromWebhook ? (j.body || {}) : {};
const dryRun = ['1', 'true', 'yes'].includes(String(q.dry_run ?? body.dry_run ?? '').toLowerCase());
return [{ json: { settings, dry_run: dryRun, source: fromWebhook ? 'webhook' : 'schedule', sample_values: dryRun ? (body.values || []) : [] } }];

const run = $('Prepare run').first().json;
const s = run.settings;
const res = run.dry_run ? { values: run.sample_values } : $input.first().json;
const fetch_error = res.error ? (res.error.message || 'could not read the sheet') : null;
const values = res.values || [];

const header = (values[0] || []).map((h) => String(h).trim().toLowerCase().replace(/\s+/g, '_'));
const col = (row, name) => String(row[header.indexOf(name)] ?? '').trim();

function phoneE164(raw) {
  let p = raw.replace(/[\s()-]/g, '');
  if (!p) return '';
  if (p.startsWith('00')) p = '+' + p.slice(2);
  else if (p.startsWith('0')) p = s.default_country_code + p.slice(1);
  else if (!p.startsWith('+')) p = '+' + p;
  return /^\+[1-9]\d{7,14}$/.test(p) ? p : null;
}
// Stable string of the properties, used to skip rows that have not changed since the last sync.
const fingerprint = (props) => JSON.stringify(Object.keys(props).sort().map((k) => [k, props[k]]));

const store = $getWorkflowStaticData('global');
const synced = store.synced ??= {};
const seen = {};
const upserts = [];
const statuses = [];
let unchanged = 0;

values.slice(1).forEach((row, i) => {
  const rowNumber = i + 2;
  if (!row.some((c) => String(c).trim())) return;
  const current = col(row, 'crm_status');
  const fail = (reason) => statuses.push({ row: rowNumber, status: `error: ${reason}`, current });

  const email = col(row, 'email').toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail(`invalid email "${col(row, 'email')}"`);
  if (seen[email]) return fail(`duplicate of row ${seen[email]}`);
  seen[email] = rowNumber;

  const phone = phoneE164(col(row, 'phone'));
  if (phone === null) return fail(`invalid phone "${col(row, 'phone')}"`);
  const stage = col(row, 'stage');
  const lifecyclestage = s.stages[stage];
  if (stage && !lifecyclestage) return fail(`unknown stage "${stage}", use ${Object.keys(s.stages).join(', ')}`);

  const [firstname, ...rest] = col(row, 'name').split(/\s+/);
  const props = { email, firstname: firstname || '', lastname: rest.join(' '), company: col(row, 'company') };
  if (phone) props.phone = phone;
  if (lifecyclestage) props.lifecyclestage = lifecyclestage;
  const owner = s.owner_ids[col(row, 'owner')];
  if (owner) props.hubspot_owner_id = owner;

  const fp = fingerprint(props);
  if (synced[email] === fp && current.startsWith('synced')) { unchanged += 1; return; }
  upserts.push({ row: rowNumber, email, properties: props, fingerprint: fp, current });
});

const batches = [];
for (let i = 0; i < upserts.length; i += s.batch_size) batches.push(upserts.slice(i, i + s.batch_size));

return [{ json: {
  dry_run: run.dry_run, source: run.source, fetch_error,
  rows: Math.max(values.length - 1, 0), unchanged, upserts, invalid: statuses,
  batches: batches.map((b) => ({ inputs: b.map((u) => ({ idProperty: 'email', id: u.email, properties: u.properties })) })),
} }];

// Turn HubSpot results into one status per row, and remember what was synced.
const plan = $('Plan sync').first().json;
const s = $('Prepare run').first().json.settings;
let responses = [];
try { responses = $('HubSpot batch upsert').all().map((i) => i.json); } catch (e) { /* nothing to upsert this run */ }

const okEmails = new Set();
const batchErrors = {};
responses.forEach((res, b) => {
  const inputs = plan.batches[b]?.inputs || [];
  if (res.error || !Array.isArray(res.results)) {
    const msg = res.error?.message || res.message || 'HubSpot request failed';
    inputs.forEach((x) => (batchErrors[x.id] = msg));
    return;
  }
  res.results.forEach((r) => okEmails.add(String(r.properties?.email || r.id || '').toLowerCase()));
  (res.errors || []).forEach((e) => (e.context?.ids || []).forEach((id) => (batchErrors[String(id).toLowerCase()] = e.message)));
});

const now = DateTime.now().toFormat('yyyy-MM-dd HH:mm');  // n8n instance timezone
const store = $getWorkflowStaticData('global');
const synced = store.synced ??= {};
const statuses = [...plan.invalid];
let synced_count = 0;
for (const u of plan.upserts) {
  if (okEmails.has(u.email)) {
    synced[u.email] = u.fingerprint;
    synced_count += 1;
    statuses.push({ row: u.row, status: `synced ${now}`, current: u.current });
  } else {
    delete synced[u.email];
    statuses.push({ row: u.row, status: `error: ${batchErrors[u.email] || 'not in HubSpot response'}`, current: u.current });
  }
}
// Only write cells whose text changes, so an unchanged sheet is not rewritten every 15 minutes.
const writes = statuses.filter((x) => x.status !== x.current).sort((a, b) => a.row - b.row);
return [{ json: {
  synced: synced_count, failed: statuses.filter((x) => x.status.startsWith('error')).length, writes,
  sheet_update: { valueInputOption: 'RAW', data: writes.map((x) => ({ range: `${s.sheet_name}!${s.status_column}${x.row}`, values: [[x.status]] })) },
} }];

const plan = $('Plan sync').first().json;
let result = null;
try { result = $('Collect results').first().json; } catch (e) { /* dry run */ }
const { batches, upserts, ...rest } = plan;
rest.upserts = upserts.map(({ row, email, properties }) => ({ row, email, properties }));
return [{ json: plan.dry_run
  ? { ...rest, would_write: plan.invalid.filter((x) => x.status !== x.current), hubspot_batches: batches }
  : { ...rest, synced: result?.synced ?? 0, failed: result?.failed ?? 0, status_cells_written: result?.writes.length ?? 0 } }];
